(function() {
    const createButton = () => {
        const chatBtnEl = document.createElement('div');

        chatBtnEl.classList.add('fn-open-chat');
        chatBtnEl.style.cssText = `
            position: absolute;
            z-index: 99;
            top: -5rem;
            left: 1rem;
            width: 4rem;
            height: 4rem;
            background: #0f385b url(/library/zendesk-chat-button-icon.svg) no-repeat center;
            box-shadow: 0 0 6px 1px rgba(0, 0, 0, 0.5);
            border-radius: 50%;
            cursor: pointer;
        `;

        return chatBtnEl;
    };

    const button = createButton();

    const addButton = button => {
        const parent = document.querySelector('.fn-sticky-footer');

        parent && parent.appendChild(button);
    };

    const removeButton = button => {
        button && button.remove();
    };

    const isLoggedIn = () => Boolean(Playtech.fetchUserDetails().sessionId);
    const getConfig = () => Playtech.Variables.zendeskChat;

    const isButtonVisible = () => {
        const { enabled, guestAvailability = true, userAvailability = true, showButton = true } = getConfig();

        if (!enabled || !showButton) {
            return false;
        }

        return isLoggedIn() ? userAvailability : guestAvailability;
    };

    const checkButtonVisibility = () => {
        if (isButtonVisible()) {
            addButton(button);
        } else {
            removeButton(button);
        }
    };

    checkButtonVisibility();

    require('core').on('page:rendered', checkButtonVisibility);
})();
