(function (){
  var GamesInfoView = require('portlets/games-info/wplayco-theme/gamesinfo.view');
  var liveGameData = require('portlets/games-info/wplayco-theme/liveGame.data');
  var LIVE_TABLE_STATUS = require('portlets/games-info/wplayco-theme/liveGame.status');
  
  GamesInfoView.prototype.reverseCounterInit = function() {
            if (this.counterInterval) {
                clearInterval(this.counterInterval);
            }

            this.counterInterval = setInterval(function() {
                this.$el.find('.fn-opening-counter').forEach(function(item) {
                    const gameCode = $(item).attr('data-game-code');
                    const data = liveGameData.getLiveData(gameCode);
                    const currentTime = new Date();
                    let ms = data.openingDateTime;

                    liveGameData.updateOpeningDateTime(gameCode, ms);
                    
                    ms = ms - currentTime;

                    if (LIVE_TABLE_STATUS.SCHEDULED !== data.status || ms <= 0) {
                        const $parentLiveBlock = $(item).parents('.fn-live-game-info');

                        $parentLiveBlock.find('.opening-main-wrapper').hide();
                        $parentLiveBlock.find('.opening-counter-shown').toggleClass('opening-counter-shown');

                        return;
                    }

                    const days = Math.floor(ms / (24 * 60 * 60 * 1000));
                    const daysms = ms % (24 * 60 * 60 * 1000);
                    const hours = Math.floor(daysms / (60 * 60 * 1000));
                    const hoursms = ms % (60 * 60 * 1000);
                    const minutes = Math.floor(hoursms / (60 * 1000));
                    const minutesms = ms % (60 * 1000);
                    const sec = Math.floor(minutesms / 1000);

                    const dayString = days === 0 ? '' : days < 10 ? '0' + days + ':' : days + ':';
                    const hoursString = hours < 10 ? '0' + hours : hours;
                    const minutesString = minutes < 10 ? '0' + minutes : minutes;
                    const secString = sec < 10 ? '0' + sec : sec;

                    item.innerText = dayString + hoursString + ":" + minutesString + ":" + secString;
                });
            }.bind(this), 1000);
        }
})();
