document.body.addEventListener("click", function(e) {
    if (e.target.className.indexOf("fn-login-btn") > -1) {
        var u = e.target.form.querySelector("[name='userName']").value;
        var p = e.target.form.querySelector("[name='password']").value;
        Playtech.WplayLoginData = {};
        Playtech.WplayLoginData.username = u;
        Playtech.WplayLoginData.password = p;
    } else if (e.target.className.indexOf("fn-submit") > -1 && (document.location.pathname === Playtech.Variables.registrationURL || Playtech.Variables.sportRegistrationURL)) {
        var e = document.querySelector(".registration-wrappper [name='email']") && document.querySelector(".registration-wrappper [name='email']").value;
        var p = document.querySelector(".registration-wrappper [name='password']") && document.querySelector(".registration-wrappper [name='password']").value;
        Playtech.WplayLoginData = {};
        Playtech.WplayLoginData.username = e;
        Playtech.WplayLoginData.email = e;
        Playtech.WplayLoginData.password = p;
    }
}, false);

document.body.addEventListener('click', function (ev) {
    if (ev && ev.target && ev.target.dataset && ev.target.dataset.nativeAction) {
        switch (ev.target.dataset.nativeAction) {
            case 'close':
                try {
                    window.webkit.messageHandlers.observe.postMessage('closeWebView');
                } catch (e) {}
                break;
            case 'cashier':
            case 'close':
                try {
                    window.webkit.messageHandlers.observe.postMessage('closeWebView:openCashier');
                } catch (e) {}
                break;
            case 'game':
                try {
                    window.webkit.messageHandlers.observe.postMessage('closeWebView:openGame:' + ev.target.dataset.nativeGameCode);
                } catch (e) {}
                break;
        }
    }
});

