(function ($) {

  var cb_stack = {};

  /** Add event listener to elements which not yet in the DOM
   * added to document element
   * by Igor Raihlin 13.11.2019
   *
   * Params:
   * @evt: string of events seaprated with spaces
   * @selector: string - Sizzle selector to match future element
   * @cb: function - registered callback
   * @options: [optional] array - addEventListener options, default: {capture:true}
   *
   * Usage: $.live(@evt, @selector, @cb, [@options])
   */
  $.live = $.live ? $.live : $.fn.live = function (evt, selector, cb, options) {

    options = options || false;
    evt = evt.split(' ');

    evt.forEach(function (_evt) {
      cb_stack[_evt] = cb_stack[_evt] || {};

      if ("function" === typeof cb) {
        cb_stack[_evt][cb] = function (e) {
          document.querySelectorAll(selector).forEach(function (_$el) {
            if (e.target === _$el) {
              cb(e);
            }
          });
        };
        document.addEventListener(_evt, cb_stack[_evt][cb], options);
      }
    });
    return this;
  };

  /** Remove event listener from document element
   * by Igor Raihlin 13.11.2019
   *
   * Params:
   * @evt: string of events seaprated with spaces
   * @cb: function - registered callback
   * @options: [optional] array - removeEventListener options, default: {capture:true}
