(function () {
  class PromoWidget {
    constructor(
        restrictedUrls,
        tagName,
        buttonLogoUrl,
        logoUrl,
        faqHref, 
        customClass,
        drawDates
    ) {
        this.restrictedUrls = restrictedUrls;
        this.tagName = tagName;
        this.buttonLogoUrl = buttonLogoUrl;
        this.logoUrl = logoUrl;
        this.faqHref = faqHref;
        this.customClass = customClass;
        this.drawDates = drawDates;
    }

    init() {

        var currentUrl = document.location.pathname;
        var _Playtech$fetchUserDe = Playtech.fetchUserDetails(),
            vipLevel = _Playtech$fetchUserDe.vipLevel;

        var btn = document.querySelector(`.toggle-promo-btn.${this.customClass}`);

        addCounterWidget(this.customClass);

        if (btn) btn.remove();

        if (this.restrictedUrls.includes(currentUrl) || !this.restrictedUrls[0]) {
            var promoCounterToggleBtn = document.createElement('button');
            var torrneosToggleBtnLogo = document.createElement('img');
            var promoCounterCloseBtn = document.querySelector(`.${this.customClass} .promo-wrapper__close-button`);
            var torreoswTicketsNumber = document.querySelector(`.${this.customClass} .tickets-amount__value`);
            var promoCounterOverlay = document.querySelector(`.${this.customClass} .promo-wrapper-overlay`);
            var promoCounterWrapper = document.querySelector('.promoCounter-promo');
            var isPageCasino = promoCounterWrapper.classList.contains('casino');
            var promoWrapperLogo = document.querySelector(`.${this.customClass} .promo-wrapper__logo`);
            var promoFaqHref = document.querySelector(`.${this.customClass} .promo-footer__action`);

            promoCounterToggleBtn.classList.add('toggle-promo-btn');
            promoCounterToggleBtn.classList.add(this.customClass);
            torrneosToggleBtnLogo.setAttribute('src', this.buttonLogoUrl);
            promoWrapperLogo.setAttribute('src', this.logoUrl);
            promoFaqHref.setAttribute('href', this.faqHref);
            promoCounterToggleBtn.appendChild(torrneosToggleBtnLogo);

            var promoCounterWrapperCustom = document.querySelector(`.promoCounter-promo.${this.customClass}`);

            if ((vipLevel >= 17 && vipLevel <= 20) && this.restrictedUrls[0] != currentUrl && isPageCasino && document.querySelectorAll(`.toggle-promo-btn.${this.customClass}`).length === 0) {
                document.body.appendChild(promoCounterToggleBtn);
            }


            function CountdownTracker(label, value) {
                var el = document.createElement('span');
                el.className = 'flip-clock__piece';
                el.innerHTML = '<span class="flip-clock__card card"><span class="card__top"></span><span class="card__bottom"></span><span class="card__back"><span class="card__bottom"></span><span class="card__separator"></span></span></span>' + '<span class="flip-clock__slot">' + label + '</span>';

                this.el = el;

                var top = el.querySelector(`.card__top`),
                    bottom = el.querySelector(`.card__bottom`),
                    back = el.querySelector(`.card__back`),
                    backBottom = el.querySelector(`.card__back .card__bottom`);

                this.update = function (val) {
                    val = ('0' + val).slice(-2);
                    if (val !== this.currentValue) {
                        if (this.currentValue >= 0) {
                            back.setAttribute('data-value', this.currentValue);
                            bottom.setAttribute('data-value', this.currentValue);
                        }

                        this.currentValue = val;
                        top.innerText = this.currentValue;
                        backBottom.setAttribute('data-value', this.currentValue);
                        this.el.classList.remove('flip'); void this.el.offsetWidth; this.el.classList.add('flip');
                    }
                };

                this.update(value);
            }


            function getTimeRemaining(endtime) {
                var t = Date.parse(endtime) - Date.parse(new Date());
                var c = document.querySelector('.flip-clock');
                var timeRemaining = {
                    'Total': t,
                    'Días': Math.floor(t / (1000 * 60 * 60 * 24)),
                    'Horas': Math.floor((t / (1000 * 60 * 60)) % 24),
                    'Minutos': Math.floor((t / 1000 / 60) % 60)
                };

                c.setAttribute('title', "".concat(timeRemaining['Días'], " d\xEDas, ").concat(timeRemaining['Horas'], " horas, ").concat(timeRemaining['Minutos'], " minutos"));

                return timeRemaining;
            }

            function getTime() {
                var t = new Date();
                return { 'Total': t, 'Horas': t.getHours() % 12, 'Minutos': t.getMinutes() };
            }

            function Clock(countdown, customClass) {
                countdown = countdown ? new Date(Date.parse(countdown)) : false;
                var updateFn = countdown ? getTimeRemaining : getTime;
                this.el = document.querySelector(`.${customClass} .flip-clock`);
                var trackers = {},
                    t = updateFn(countdown), key, timeinterval;

                for (key in t) {
                    if (key === 'Total') { continue; }
                    trackers[key] = new CountdownTracker(key, t[key]); this.el.appendChild(trackers[key].el);
                }

                var i = 0;

                function updateClock() {
                    timeinterval = requestAnimationFrame(updateClock);
                    if (i++ % 10) { return; }

                    var t = updateFn(countdown);
                    if (t.Total < 0) {
                        cancelAnimationFrame(timeinterval);

                        for (key in trackers) {
                            trackers[key].update(0);
                        }
                        return;
                    }

                    for (key in trackers) {
                        trackers[key].update(t[key]);
                    }
                }

                setTimeout(updateClock, 5000);
            }

            var deadline = new Date();

            if (this.drawDates) {
                var getNextDate = function() {
                    var nextDate;
                    this.drawDates.some(function (date) {
                        nextDate = new Date(date);
                        return new Date(date) > new Date();
                    });

                    nextDate.setUTCDate(nextDate.getUTCDate());
                    nextDate.setUTCHours(nextDate.getUTCHours());

                    return nextDate.toUTCString();
                };

                deadline = getNextDate();
            } else {
                var t = new Date();
                deadline.setUTCDate(deadline.getUTCDate() + ((7 - deadline.getUTCDay()) % 7 + 2) % 7);
                deadline.setUTCHours(16, 59, 59, 99);

                if (deadline.getUTCMonth === t.getUTCMonth && deadline.getUTCDate() === t.getUTCDate() && deadline.getUTCHours() < t.getUTCHours()) {
                    deadline.setUTCDate(t.getUTCDate() + (7 - t.getUTCDay()) % 7 + 2);
